import{_ as u,a0 as o,w as p,s as d,ao as n,I as l,x as s,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"构建基础包的基础知识 | LCTT x X-CMD","titleTemplate":false,"description":"构建基础包的基础知识 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"构建基础包的基础知识 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"构建基础包的基础知识 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it","title":"构建基础包的基础知识","tag":"202111","desc":""},"relativePath":"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it.md","filePath":"[post].md"}'),r={name:"202111/20211019 What is Build Essential Package in Ubuntu- How to Install it.md"};function b(g,t,h,k,m,f){const i=o("Link");return p(),d("div",null,[t[27]||(t[27]=n('<h1 id="构建基础包的基础知识" tabindex="-1">构建基础包的基础知识 <a class="header-anchor" href="#构建基础包的基础知识" aria-label="Permalink to “构建基础包的基础知识”">​</a></h1><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/Build-Essential-Ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><blockquote><p>这是一篇快速提示，旨在给 Ubuntu 的新用户解释构建基础包是什么、它的用处和安装步骤。</p></blockquote><p>在 Ubuntu 中安装构建基础包（<code>build-essential</code>），只需要在终端中简单输入这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt install build-essential</span></span></code></pre></div><p>但围绕它有几个问题，你可能想知道答案：</p><ul><li>什么是构建基础包？</li><li>它包含什么内容？</li><li>为什么要安装它（如果安装的话）？</li><li>如何安装它？</li><li>如何删除它？</li></ul><h3 id="什么是-ubuntu-中的构建基础包" tabindex="-1">什么是 Ubuntu 中的构建基础包？ <a class="header-anchor" href="#什么是-ubuntu-中的构建基础包" aria-label="Permalink to “什么是 Ubuntu 中的构建基础包？”">​</a></h3><p>构建基础包（<code>build-essential</code>）实际上是属于 Debian 的。在它里面其实并不是一个软件。它包含了创建一个 Debian 包（<code>.deb</code>）所需的软件包列表。这些软件包包括 <code>libc</code>、<code>gcc</code>、<code>g++</code>、<code>make</code>、<code>dpkg-dev</code> 等。构建基础包包含这些所需的软件包作为依赖，所以当你安装它时，你只需一个命令就能安装所有这些软件包。</p><p>请不要认为构建基础包是一个可以在一个命令中神奇地安装从 Ruby 到 Go 的所有开发工具的超级软件包。它包含一些开发工具，但不是全部。</p><h4 id="你为什么要安装构建基础包" tabindex="-1">你为什么要安装构建基础包？ <a class="header-anchor" href="#你为什么要安装构建基础包" aria-label="Permalink to “你为什么要安装构建基础包？”">​</a></h4><p>它用来从应用的源代码创建 DEB 包。一个普通用户不会每天都去创建 DEB 包，对吗？</p>',12)),l("p",null,[t[3]||(t[3]=s("然而，有些用户可能会使用他们的 Ubuntu Linux 系统进行软件开发。如果你想 ",-1)),e(i,{href:"https://itsfoss.com/run-c-program-linux/"},{default:a(()=>[...t[0]||(t[0]=[s("在 Ubuntu 中运行 c 程序",-1)])]),_:1}),t[4]||(t[4]=s("，你需要 gcc 编译器。如果你想 ",-1)),e(i,{href:"https://itsfoss.com/c-plus-plus-ubuntu/"},{default:a(()=>[...t[1]||(t[1]=[s("在 Ubuntu 中运行 C++ 程序",-1)])]),_:1}),t[5]||(t[5]=s("，你需要 g++ 编译器。如果你要使用一个不寻常的、只能从源代码中获得的软件，你的系统会抛出 “",-1)),e(i,{href:"https://itsfoss.com/make-command-not-found-ubuntu/"},{default:a(()=>[...t[2]||(t[2]=[s("make 命令未找到的错误",-1)])]),_:1}),t[6]||(t[6]=s("”，因为你需要先安装 ",-1)),t[7]||(t[7]=l("code",null,"make",-1)),t[8]||(t[8]=s(" 工具。",-1))]),t[28]||(t[28]=l("p",null,"当然，所有这些都可以单独安装。然而，利用构建基础包的优势，一次性安装所有这些开发工具要容易得多。这就是你得到的好处。",-1)),l("p",null,[t[10]||(t[10]=s("这就像 ",-1)),e(i,{href:"https://itsfoss.com/install-media-codecs-ubuntu/"},{default:a(()=>[...t[9]||(t[9]=[s("ubuntu-restricted-extras 包允许你一次安装几个媒体编解码器",-1)])]),_:1}),t[11]||(t[11]=s("。",-1))]),t[29]||(t[29]=n('<p>现在你知道了这个包的好处，让我们看看如何安装它。</p><h3 id="在-ubuntu-linux-中安装构建基础包" tabindex="-1">在 Ubuntu Linux 中安装构建基础包 <a class="header-anchor" href="#在-ubuntu-linux-中安装构建基础包" aria-label="Permalink to “在 Ubuntu Linux 中安装构建基础包”">​</a></h3><p>在 Ubuntu 中按 <code>Ctrl+Alt+T</code> 快捷键打开终端，输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>使用 <code>sudo</code> 命令，你会被要求输入你的账户密码。当你输入时，屏幕上没有任何显示。这没问题。这在大多数 Linux 系统中都是这样的。盲打输入你的密码，然后按回车键。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/apt-update.png?resize=800%2C467&amp;ssl=1" alt=""></p><p><code>apt update</code> 命令刷新了本地软件包的缓存。这对于一个新安装的 Ubuntu 来说是必不可少的。</p><p>之后，运行下面的命令来安装构建基础包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install build-essential</span></span></code></pre></div><p>它应该显示所有要安装的软件包。当要求确认时按 <code>Y</code>：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/install-build-essential-ubuntu.png?resize=800%2C434&amp;ssl=1" alt=""></p><p>等待安装完成。就好了。</p><h3 id="从-ubuntu-中删除构建基础包" tabindex="-1">从 Ubuntu 中删除构建基础包 <a class="header-anchor" href="#从-ubuntu-中删除构建基础包" aria-label="Permalink to “从 Ubuntu 中删除构建基础包”">​</a></h3><p>保留这些开发工具不会损害你的系统。但如果你的磁盘空间不足，你可以考虑删除它。</p><p>在 Ubuntu 中，由于有 <code>apt remove</code> 命令，删除软件很容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove build-essential</span></span></code></pre></div><p>运行 <code>autoremove</code> 命令来删除剩余的依赖包也是一个好主意：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove</span></span></code></pre></div><p>你现在知道了构建基础包的基础知识（双关语）。希望对你有用~</p><hr>',20)),l("p",null,[t[13]||(t[13]=s("via: ",-1)),e(i,{href:"https://itsfoss.com/build-essential-ubuntu/"},{default:a(()=>[...t[12]||(t[12]=[s("https://itsfoss.com/build-essential-ubuntu/",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=s("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...t[14]||(t[14]=[s("Abhishek Prakash",-1)])]),_:1}),t[19]||(t[19]=s(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[15]||(t[15]=[s("lujun9972",-1)])]),_:1}),t[20]||(t[20]=s(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[16]||(t[16]=[s("geekpi",-1)])]),_:1}),t[21]||(t[21]=s(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[17]||(t[17]=[s("wxy",-1)])]),_:1})]),l("p",null,[t[24]||(t[24]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[22]||(t[22]=[s("LCTT",-1)])]),_:1}),t[25]||(t[25]=s(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:a(()=>[...t[23]||(t[23]=[s("Linux中国",-1)])]),_:1}),t[26]||(t[26]=s(" 荣誉推出",-1))])])}const c=u(r,[["render",b]]);export{T as __pageData,c as default};
